    wire [ADDR_WIDTH-1:0] rnext;
    wire                  push;
    wire                  pop;
    reg  [ADDR_WIDTH:0]   mOutPtr = 1'b0;
    reg                   empty_n = 1'b0;
    reg                   full_n = 1'b1;
    // has almost full?  no 
    // has output register? 
    reg                   dout_vld = 1'b0;//yes 

//------------------------Instantiation------------------
    HT_ADD_QUANT_fifo_w256_d32_A_ram 
    #(  .MEM_STYLE  (MEM_STYLE),
        .DATA_WIDTH (DATA_WIDTH),
        .ADDR_WIDTH (ADDR_WIDTH),
        .DEPTH      (DEPTH)
    ) U_HT_ADD_QUANT_fifo_w256_d32_A_ram (
        .clk        (clk),
        .reset      (reset),
        .we         (push),
        .waddr      (waddr),
        .din        (if_din),
        .raddr      (rnext), 
        .rden       (pop),   
        .dout       (if_dout)
    );

//------------------------Task and function--------------

//------------------------Body---------------------------
    // has num_data_valid ? 
    assign if_fifo_cap = DEPTH + 1; // yes  

    // has almost full ? 
    assign if_full_n  = full_n; //no 

    // has output register? 
    assign if_empty_n = dout_vld;  // yes
    assign pop        = empty_n & if_read_ce & (if_read | ~dout_vld); // yes 
    assign push       = full_n & if_write_ce & if_write;
    assign wnext      = !push                ? waddr :
                        (waddr == DEPTH - 1) ? 1'b0  :
                        waddr + 1'b1;
    assign rnext      = !pop                 ? raddr :
                        (raddr == DEPTH - 1) ? 1'b0  :
                        raddr + 1'b1;

    // waddr
    always @(posedge clk ) begin
        if (reset == 1'b1)
            waddr <= 1'b0;
        else
            waddr <= wnext;
    end

    // raddr
    always @(posedge clk ) begin
        if (reset == 1'b1)
            raddr <= 1'b0;
        else
            raddr <= rnext;
    end

    // mOutPtr
    always @(posedge clk ) begin
        if (reset == 1'b1)
            mOutPtr <= 1'b0;
        else if (push & ~pop)
            mOutPtr <= mOutPtr + 1'b1;
        else if (~push & pop)
            mOutPtr <= mOutPtr - 1'b1;
    end

    // full_n
    always @(posedge clk ) begin
        if (reset == 1'b1)
            full_n <= 1'b1;
        else if (push & ~pop)
            full_n <= (mOutPtr != DEPTH - 1);
        else if (~push & pop)
            full_n <= 1'b1;
    end

    // almost_full_n 

    // empty_n
    always @(posedge clk ) begin
        if (reset == 1'b1)
            empty_n <= 1'b0;
        else if (push & ~pop)
            empty_n <= 1'b1;
        else if (~push & pop)
            empty_n <= (mOutPtr != 1'b1);
    end

